-- AlterTable
ALTER TABLE `cliente` ADD COLUMN `es_oee` BOOLEAN NULL;

-- AlterTable
ALTER TABLE `padron_ruc` ADD COLUMN `es_oee` BOOLEAN NULL;

-- CreateIndex
CREATE INDEX `padron_ruc_es_oee_idx` ON `padron_ruc`(`es_oee`);

-- DataMigration: siembra del catálogo de Organismos y Entidades del Estado (OEE).
--
-- Va en la misma migración que la columna porque una `padron_ruc.es_oee` vacía no es un estado
-- válido de la aplicación: sin la marca, todo DE dirigido a un organismo del Estado sale como B2B y
-- SIFEN lo rechaza con el código 1332 (validación D202b, Nota Técnica N° 20). La columna y su
-- contenido inicial son la misma unidad de despliegue.
--
-- Los 392 RUC salen de `src/data/oeeRucs.json`, derivado del catálogo de entidades contratantes de
-- la DNCP cruzado contra el padrón local (la DNCP identifica a sus entidades con un código interno y
-- nunca publica su RUC). La derivación completa, los matches ambiguos que se rechazaron a mano y lo
-- que el catálogo no cubre están en `src/data/README-oee.md`.
--
-- Idempotente por construcción (un UPDATE a TRUE se puede repetir) y tolerante a un padrón vacío:
-- sobre una base nueva, sin importar todavía los ZIP del DNIT, afecta 0 filas y no falla. Para
-- resembrar después de una importación batch está `npm run seed:oee`, que hace exactamente esto.
--
-- NO se marca `es_oee = FALSE` en el resto del padrón: FALSE significa "verificado que no lo es" y
-- no verificamos 2M de RUC. El default es NULL = "no lo sabemos", que se comporta como el histórico.
UPDATE `padron_ruc` SET `es_oee` = TRUE WHERE `ruc` IN (
  '80000004','80000089','80000124','80000181','80000215','80000433','80000482','80000489','80000492','80000493',
  '80000552','80000564','80000638','80000643','80000725','80000856','80000905','80001097','80001140','80001176',
