-- Los Clientes ya existentes que apunten a uno de esos RUC quedan marcados en el acto. No es
-- estrictamente necesario —`emitirFactura` y `genericoService.getDatosByRuc` releen `es_oee` del
-- padrón y lo persisten en el Cliente antes de armar el XML, así que la primera emisión posterior ya
-- saldría bien— pero deja la base consistente desde el minuto cero en vez de "consistente después de
-- la próxima factura".
--
-- El JOIN normaliza `cliente.ruc` a la BASE que guarda el padrón: sin el dígito verificador
-- ("80005190-4" -> "80005190") y sin ceros a la izquierda. Se acota a CONTRIBUYENTE porque B2G
-- exige informar RUC (iNatRec=1): un receptor por cédula nunca es B2G.
UPDATE `cliente` c
JOIN `padron_ruc` p ON p.`ruc` = TRIM(LEADING '0' FROM SUBSTRING_INDEX(c.`ruc`, '-', 1))
SET c.`es_oee` = TRUE
WHERE c.`situacion_tributaria` = 'CONTRIBUYENTE' AND p.`es_oee` = TRUE;
